/**
 * One evolution edge: `trigger` picks the test in EVO_CHECK, the other fields are that trigger's conditions.
 * `level`, `item` (stones) and `gender` + item are filled in; the other kinds are typed here and stubbed in EVO_CHECK for later.
 * @typedef {{ from: string, to: string } & (
 *   { trigger: 'level', minLevel: number } |
 *   { trigger: 'item', item: string } |
 *   { trigger: 'friendship', minHappiness: number, time?: 'day' | 'night' } |
 *   { trigger: 'trade', heldItem?: string, withSpecies?: string } |
 *   { trigger: 'heldItem', heldItem: string, time?: 'day' | 'night' } |
 *   { trigger: 'time', time: 'day' | 'night' | 'dusk', minLevel?: number } |
 *   { trigger: 'move', move?: string, moveType?: string } |
 *   { trigger: 'location', location: string } |
 *   { trigger: 'gender', gender: 'male' | 'female', minLevel?: number, item?: string } |
 *   { trigger: 'stats', minLevel: number, compare: 'atk>def' | 'atk<def' | 'atk=def' } |
 *   { trigger: 'party', minLevel: number, partySpecies?: string, partyType?: string } |
 *   { trigger: 'special', note: string }
 * )} Evolution
 */
// Source: PokeAPI v2 evolution-chain + pokemon + pokemon-species, snapshot 2026-10-19/20 (static; never fetched at runtime).
// Scope: Pokémon in this game = the National numbers in the DEX_MODELS literal below (477); an edge is kept when both ends are
// in it. Exception: Snorunt > Froslass (asked for by name).
// Level-only = trigger level-up with min_level and no other condition. Stones = use-item with one of the 10 stones in ITEMS.
// Rows that only apply to a regional form are ignored (Alolan Vulpix > Ninetales by Ice Stone, Galarian Meowth > Perrserker...).
// Cross-checked with the Serebii SV/SwSh Pokédex evolution chains: 2026-10-19 Charmander 16/36, Caterpie 7/10, Weedle 7/10,
