const EVO_CHECK = { // (mon, edge, item used or undefined on a level-up) => can it evolve now? Stubs stay false until implemented
  level: (m, e, item) => !item && m.level >= e.minLevel,
  item: (m, e, item) => item === e.item,
  gender: (m, e, item) => m.gender === e.gender && (e.item ? item === e.item : !item && m.level >= e.minLevel),
  friendship: () => false, trade: () => false, heldItem: () => false, time: () => false, move: () => false,
  location: () => false, stats: () => false, party: () => false, special: () => false,
};
const evoFor = (m, item) => EVOLUTIONS.find(e => e.from === m.key && EVO_CHECK[e.trigger](m, e, item));
